    offset = 0
    limit = 500

    while True:
        logs = query_logs(service='api', level='WARN', limit=limit, offset=offset)
        items = logs.get('items', [])

        if not items:
            break

        for item in items:
            if 'cache' in item.get('msg', '').lower():
                total_count += 1

        # Check if we've reached the end based on total or if items returned are less than limit
        if len(items) < limit:
            break

        offset += limit
        # Safety break to prevent infinite loop if API is buggy
        if offset > 10000:
            break

    print(total_count)

